select x.customer_id, x.last_order_at
from (
  select paid_orders.customer_id, max(paid_orders.created_at) as last_order_at
  from (
    select o.id, o.customer_id, o.created_at
    from public.orders o
    where o.status = 'paid'
  ) paid_orders
  join public.payments p on p.order_id = paid_orders.id
  group by paid_orders.customer_id
) x
where x.last_order_at < current_date - interval '30 days';
